def valid_partial_grid(board):
    seen = set()
    for r, row in enumerate(board):
        for c, value in enumerate(row):
            if value == '.': continue
            keys = [('row', r, value), ('col', c, value), ('box', r//3, c//3, value)]
            if any(key in seen for key in keys): return False
            seen.update(keys)
    return True

